def make(n):
    # produce versions like "1.0a1", "1.0a2", … up to n
    return [[f"1.0a{i}"] for i in range(1, n+1)]

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append('9' * i)
    version = '.'.join(chunks) + '-alpha.1'
    return [(version,)]
